// Package parity_test compares the Go repo-intel implementation with the committed outputs of the
// Node implementation (dev-digest d1c9093): symbols, references, facts and content hashes of the
// extraction corpus, import-graph edges, PageRank and percentiles, the repo map, token counts and
// the clone walk (NFR3008). The goldens are generated by testdata/gen (see its README) and are
// never edited here; the D3019 deviation fixtures compare against hand-written expectations.
package parity_test

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/google/go-cmp/cmp"
	"github.com/google/go-cmp/cmp/cmpopts"

	"dev-digest-go/backend/internal/repointel/adapters/clonetree"
	"dev-digest-go/backend/internal/repointel/adapters/tokenizer"
	"dev-digest-go/backend/internal/repointel/adapters/treesitter"
	"dev-digest-go/backend/internal/repointel/domain"
	"dev-digest-go/backend/internal/repointel/domain/importgraph"
	"dev-digest-go/backend/internal/repointel/domain/rank"
)

const (
	testdata = "testdata"
	// pagerankTolerance is the NFR3008 bound on |pagerank_go - pagerank_node|.
	pagerankTolerance = 1e-12
)

// loadJSON decodes a JSON file below testdata.
func loadJSON(t *testing.T, rel string, v any) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(testdata, rel))
	if err != nil {
		t.Fatalf("read %s: %v", rel, err)
	}
	if err := json.Unmarshal(data, v); err != nil {
		t.Fatalf("decode %s: %v", rel, err)
	}
}

// ---- extraction (AC3042, AC3043, AC3045, AC3047) ----

type goldenSymbol struct {
	Name      string `json:"name"`
	Kind      string `json:"kind"`
	Line      int    `json:"line"`
	EndLine   int    `json:"endLine"`
	Exported  bool   `json:"exported"`
	Signature string `json:"signature"`
}

type goldenReference struct {
	ToSymbol string `json:"toSymbol"`
	Line     int    `json:"line"`
}

type goldenFile struct {
	Path        string            `json:"path"`
	Outcome     string            `json:"outcome"`
	ContentHash string            `json:"contentHash"`
	Symbols     []goldenSymbol    `json:"symbols"`
	References  []goldenReference `json:"references"`
	Endpoints   []string          `json:"endpoints"`
	Crons       []string          `json:"crons"`
}

func TestParity_Extract(t *testing.T) {
	var golden struct {
		Files []goldenFile `json:"files"`
	}
	loadJSON(t, "goldens/extract.json", &golden)
	if len(golden.Files) == 0 {
		t.Fatal("extract.json holds no files")
	}
	analyzer := treesitter.New()

	for _, g := range golden.Files {
		t.Run(g.Path, func(t *testing.T) {
			if g.Outcome != "indexed" {
				t.Fatalf("golden outcome = %q, the corpus only holds indexed files", g.Outcome)
			}
			raw, err := os.ReadFile(filepath.Join(testdata, "corpus", "extract", filepath.FromSlash(g.Path)))
			if err != nil {
				t.Fatalf("read fixture: %v", err)
			}
			text := domain.DecodeText(raw)

			if got := domain.ContentHash(text); got != g.ContentHash {
				t.Errorf("ContentHash(%s) = %s, want %s", g.Path, got, g.ContentHash)
			}

			ex, err := analyzer.Extract(t.Context(), g.Path, text)
			if err != nil {
				t.Fatalf("Extract(%s) error = %v", g.Path, err)
			}
			gotSyms := make([]goldenSymbol, len(ex.Symbols))
			for i, s := range ex.Symbols {
				gotSyms[i] = goldenSymbol{s.Name, s.Kind, s.Line, s.EndLine, s.Exported, s.Signature}
			}
			if diff := cmp.Diff(g.Symbols, gotSyms, sortOpt[goldenSymbol](), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("symbols of %s mismatch (-node +go):\n%s", g.Path, diff)
			}
			gotRefs := make([]goldenReference, len(ex.References))
			for i, r := range ex.References {
				gotRefs[i] = goldenReference{r.Name, r.Line}
			}
			if diff := cmp.Diff(g.References, gotRefs, sortOpt[goldenReference](), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("references of %s mismatch (-node +go):\n%s", g.Path, diff)
			}

			facts, _ := domain.ExtractFacts(g.Path, text)
			if diff := cmp.Diff(g.Endpoints, facts.Endpoints, cmpopts.SortSlices(strings.Compare), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("endpoints of %s mismatch (-node +go):\n%s", g.Path, diff)
			}
			if diff := cmp.Diff(g.Crons, facts.Crons, cmpopts.SortSlices(strings.Compare), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("crons of %s mismatch (-node +go):\n%s", g.Path, diff)
			}
		})
	}
}

// sortOpt compares slices of comparable structs as multisets.
func sortOpt[T comparable]() cmp.Option {
	return cmpopts.SortSlices(func(a, b T) bool { return fmt.Sprintf("%+v", a) < fmt.Sprintf("%+v", b) })
}

// TestParity_ExtractCoversCorpus keeps the golden list and the corpus directory in step: a
// fixture without a golden (or the reverse) would silently escape the comparison.
func TestParity_ExtractCoversCorpus(t *testing.T) {
	var golden struct {
		Files []goldenFile `json:"files"`
	}
	loadJSON(t, "goldens/extract.json", &golden)
	want := make([]string, 0, len(golden.Files))
	for _, g := range golden.Files {
		want = append(want, g.Path)
	}
	root := filepath.Join(testdata, "corpus", "extract")
	var got []string
	err := filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(root, p)
		got = append(got, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		t.Fatalf("walk corpus: %v", err)
	}
	slices.Sort(want)
	slices.Sort(got)
	if diff := cmp.Diff(want, got); diff != "" {
		t.Errorf("extract corpus files vs extract.json (-golden +disk):\n%s", diff)
	}
}

// ---- import graph (AC3049, AC3050) ----

// sourceImports returns the SourceImports of a clone: read through the confined reader, decode
// like the indexer, parse with tree-sitter. A file that cannot be read or parsed has none.
func sourceImports(root string) importgraph.SourceImports {
	fs := clonetree.New()
	analyzer := treesitter.New()
	return func(ctx context.Context, file string) domain.FileImports {
		raw, err := fs.ReadFile(root, file)
		if err != nil {
			return domain.FileImports{}
		}
		imports, err := analyzer.Imports(ctx, file, domain.DecodeText(raw))
		if err != nil {
			return domain.FileImports{}
		}
		return imports
	}
}

func buildEdges(t *testing.T, root string, files []string) [][2]string {
	t.Helper()
	g, _, err := importgraph.Build(t.Context(), clonetree.New(), root, files, sourceImports(root))
	if err != nil {
		t.Fatalf("Build(%s) error = %v", root, err)
	}
	out := make([][2]string, len(g.Edges))
	for i, e := range g.Edges {
		out[i] = [2]string{e.From, e.To}
	}
	return out
}

func edgeSetOpt() cmp.Option {
	return cmpopts.SortSlices(func(a, b [2]string) bool {
		if a[0] != b[0] {
			return a[0] < b[0]
		}
		return a[1] < b[1]
	})
}

func walkFiles(t *testing.T, root string) []string {
	t.Helper()
	res, err := clonetree.New().Walk(t.Context(), root)
	if err != nil {
		t.Fatalf("Walk(%s) error = %v", root, err)
	}
	return res.Files
}

// knownGraphDeviations are Node edges that the spec deliberately does not reproduce. Each is
// removed from the expected set and the test then requires the edge to be absent from the Go
// result, so an exception cannot hide a different change; a stale exception (the edge is no
// longer in the golden) fails the test.
var knownGraphDeviations = map[string]map[[2]string]string{
	"corpus/graphs/externals": {
		{"main.ts", "internal/thing.ts"}: "package.json \"imports\" (#internal/*) are not resolved (spec 7.5 step 4: they never yield an edge)",
	},
	"corpus/graphs/relative": {
		{"main.ts", "other.ts"}: "'../relative/other' leaves the clone root and re-enters it through the root directory's own name; " +
			"Node resolves it against the absolute fixture path, Go confines paths to the clone (spec 7.5 step 5)",
	},
}

func TestParity_Graphs(t *testing.T) {
	var golden struct {
		Graphs []struct {
			Fixture string      `json:"fixture"`
			Files   []string    `json:"files"`
			Edges   [][2]string `json:"edges"`
		} `json:"graphs"`
	}
	loadJSON(t, "goldens/graphs.json", &golden)
	if len(golden.Graphs) == 0 {
		t.Fatal("graphs.json holds no graphs")
	}
	for _, g := range golden.Graphs {
		t.Run(filepath.Base(g.Fixture), func(t *testing.T) {
			root := filepath.Join(testdata, filepath.FromSlash(g.Fixture))
			files := walkFiles(t, root)
			if diff := cmp.Diff(g.Files, files); diff != "" {
				t.Fatalf("walked files of %s mismatch (-node +go):\n%s", g.Fixture, diff)
			}
			want := slices.Clone(g.Edges)
			for edge, reason := range knownGraphDeviations[g.Fixture] {
				i := slices.Index(want, edge)
				if i < 0 {
					t.Errorf("known deviation %v of %s is not in the golden any more (%s)", edge, g.Fixture, reason)
					continue
				}
				want = slices.Delete(want, i, i+1)
			}
			got := buildEdges(t, root, files)
			if diff := cmp.Diff(want, got, edgeSetOpt(), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("edges of %s mismatch (-node +go, known deviations removed):\n%s", g.Fixture, diff)
			}
		})
	}
}

func TestParity_GraphDeviations(t *testing.T) {
	var expected struct {
		Cases []struct {
			Name              string `json:"name"`
			Root              string `json:"root"`
			Files             []string
			FilesFromWalk     bool `json:"files_from_walk"`
			RecoverySensitive bool `json:"recovery_sensitive"`
			ExpectedEdges     []struct {
				From string `json:"from"`
				To   string `json:"to"`
			} `json:"expected_edges"`
		} `json:"cases"`
	}
	loadJSON(t, "graph-deviations.json", &expected)
	if len(expected.Cases) == 0 {
		t.Fatal("graph-deviations.json holds no cases")
	}
	for _, c := range expected.Cases {
		t.Run(c.Name, func(t *testing.T) {
			root := filepath.Join(testdata, filepath.FromSlash(c.Root))
			files := c.Files
			if c.FilesFromWalk {
				if diff := cmp.Diff(c.Files, walkFiles(t, root)); diff != "" {
					t.Fatalf("walked files of %s mismatch (-expected +go):\n%s", c.Name, diff)
				}
			}
			want := make([][2]string, len(c.ExpectedEdges))
			for i, e := range c.ExpectedEdges {
				want[i] = [2]string{e.From, e.To}
			}
			got := buildEdges(t, root, files)
			if diff := cmp.Diff(want, got, edgeSetOpt(), cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("edges of %s mismatch (-expected +go):\n%s", c.Name, diff)
			}
		})
	}
}

// ---- rank (AC3051, AC3052) ----

func TestParity_Rank(t *testing.T) {
	var golden struct {
		Cases []struct {
			Name  string      `json:"name"`
			Files []string    `json:"files"`
			Edges [][2]string `json:"edges"`
			// Result is in the order of Files.
			Result []struct {
				FilePath   string  `json:"filePath"`
				PageRank   float64 `json:"pagerank"`
				Percentile int     `json:"percentile"`
			} `json:"result"`
		} `json:"cases"`
	}
	loadJSON(t, "goldens/rank.json", &golden)
	if len(golden.Cases) == 0 {
		t.Fatal("rank.json holds no cases")
	}
	for _, c := range golden.Cases {
		t.Run(c.Name, func(t *testing.T) {
			edges := make([]domain.Edge, len(c.Edges))
			for i, e := range c.Edges {
				edges[i] = domain.Edge{From: e[0], To: e[1]}
			}
			rows := rank.FileRank(c.Files, edges)
			if len(rows) != len(c.Result) {
				t.Fatalf("FileRank(%s) returned %d rows, want %d", c.Name, len(rows), len(c.Result))
			}
			worst := 0.0
			for i, want := range c.Result {
				got := rows[i]
				if got.Path != want.FilePath {
					t.Fatalf("FileRank(%s)[%d].Path = %q, want %q", c.Name, i, got.Path, want.FilePath)
				}
				d := math.Abs(got.PageRank - want.PageRank)
				worst = math.Max(worst, d)
				if d > pagerankTolerance {
					t.Errorf("FileRank(%s) pagerank of %q = %.17g, want %.17g (diff %g > %g)", c.Name, got.Path, got.PageRank, want.PageRank, d, pagerankTolerance)
				}
				if got.Percentile != want.Percentile {
					t.Errorf("FileRank(%s) percentile of %q = %d, want %d", c.Name, got.Path, got.Percentile, want.Percentile)
				}
				if got.Rank != got.PageRank || got.Hotness != 0 {
					t.Errorf("FileRank(%s) row of %q = rank %v hotness %v, want rank == pagerank and hotness 0", c.Name, got.Path, got.Rank, got.Hotness)
				}
			}
			t.Logf("largest pagerank difference: %g", worst)
		})
	}
}

// TestParity_RankNonConvergence covers AC3052: an iteration limit that cannot converge gives
// every file 1/N and percentile 100.
func TestParity_RankNonConvergence(t *testing.T) {
	files := []string{"a.ts", "b.ts", "c.ts", "d.ts"}
	edges := []domain.Edge{{From: "a.ts", To: "b.ts"}, {From: "b.ts", To: "c.ts"}, {From: "c.ts", To: "a.ts"}, {From: "d.ts", To: "a.ts"}}
	for _, row := range rank.FileRankLimit(files, edges, 1) {
		if row.PageRank != 0.25 || row.Percentile != 100 {
			t.Errorf("FileRankLimit(limit 1) row %s = pagerank %v percentile %d, want 0.25 and 100", row.Path, row.PageRank, row.Percentile)
		}
	}
}

// ---- repo map and tokens (AC3053, AC3054) ----

func TestParity_RepoMap(t *testing.T) {
	var golden struct {
		Cases []struct {
			Name       string `json:"name"`
			Candidates []struct {
				Path      string  `json:"path"`
				Name      string  `json:"name"`
				Exported  bool    `json:"exported"`
				Signature *string `json:"signature"`
				Rank      float64 `json:"rank"`
			} `json:"candidates"`
			Results []struct {
				Budget int    `json:"budget"`
				Text   string `json:"text"`
				Tokens int    `json:"tokens"`
			} `json:"results"`
		} `json:"cases"`
	}
	loadJSON(t, "goldens/repomap.json", &golden)
	if len(golden.Cases) == 0 {
		t.Fatal("repomap.json holds no cases")
	}
	counter := tokenizer.New(nil)
	for _, c := range golden.Cases {
		t.Run(c.Name, func(t *testing.T) {
			cands := make([]domain.MapCandidate, len(c.Candidates))
			for i, x := range c.Candidates {
				cands[i] = domain.MapCandidate{Path: x.Path, Name: x.Name, Exported: x.Exported, Rank: x.Rank}
				if x.Signature != nil {
					cands[i].Signature = *x.Signature
				}
			}
			for _, want := range c.Results {
				text, tokens := rank.RenderMap(cands, counter, want.Budget)
				if text != want.Text {
					t.Errorf("RenderMap(%s, budget %d) text mismatch (-node +go):\n%s", c.Name, want.Budget, cmp.Diff(want.Text, text))
				}
				if tokens != want.Tokens {
					t.Errorf("RenderMap(%s, budget %d) tokens = %d, want %d", c.Name, want.Budget, tokens, want.Tokens)
				}
			}
		})
	}
}

func TestParity_Tokens(t *testing.T) {
	var golden struct {
		Cases []struct {
			Name   string `json:"name"`
			Text   string `json:"text"`
			Tokens int    `json:"tokens"`
		} `json:"cases"`
	}
	loadJSON(t, "goldens/tokens.json", &golden)
	if len(golden.Cases) == 0 {
		t.Fatal("tokens.json holds no cases")
	}
	counter := tokenizer.New(nil)
	for _, c := range golden.Cases {
		t.Run(c.Name, func(t *testing.T) {
			if got := counter.Count(c.Text); got != c.Tokens {
				t.Errorf("Count(%s) = %d, want %d", c.Name, got, c.Tokens)
			}
		})
	}
}

// ---- walk (AC3041 parity part; walk rules of FR3013) ----

type walkEntry struct {
	Path string `json:"path"`
	Size *int   `json:"size"`
	Link string `json:"link"`
}

type walkBulk struct {
	Dir   string `json:"dir"`
	Count int    `json:"count"`
	Ext   string `json:"ext"`
}

type walkCase struct {
	Name    string      `json:"name"`
	Entries []walkEntry `json:"entries"`
	Bulk    *walkBulk   `json:"bulk"`
}

// materialize builds the declared tree under root. Writes are confined to root by the declared
// relative paths, all of which are fixture-controlled.
func materialize(t *testing.T, root string, c walkCase) {
	t.Helper()
	for _, e := range c.Entries {
		full := filepath.Join(root, filepath.FromSlash(e.Path))
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatalf("mkdir for %s: %v", e.Path, err)
		}
		switch {
		case e.Link != "":
			if err := os.Symlink(e.Link, full); err != nil {
				t.Fatalf("symlink %s: %v", e.Path, err)
			}
		case e.Size != nil:
			if err := os.WriteFile(full, []byte(strings.Repeat("x", *e.Size)), 0o644); err != nil {
				t.Fatalf("write %s: %v", e.Path, err)
			}
		default:
			if err := os.WriteFile(full, []byte("// fixture\n"), 0o644); err != nil {
				t.Fatalf("write %s: %v", e.Path, err)
			}
		}
	}
	if c.Bulk != nil {
		dir := filepath.Join(root, filepath.FromSlash(c.Bulk.Dir))
		if err := os.MkdirAll(dir, 0o755); err != nil {
			t.Fatalf("mkdir bulk: %v", err)
		}
		for i := range c.Bulk.Count {
			name := fmt.Sprintf("f%05d%s", i, c.Bulk.Ext)
			if err := os.WriteFile(filepath.Join(dir, name), []byte("// fixture\n"), 0o644); err != nil {
				t.Fatalf("write bulk %s: %v", name, err)
			}
		}
	}
}

func TestParity_Walk(t *testing.T) {
	var cases struct {
		Cases []walkCase `json:"cases"`
	}
	loadJSON(t, "corpus/walk/cases.json", &cases)
	var golden struct {
		Cases []struct {
			Name  string `json:"name"`
			Files []string
			Stats struct {
				TotalCandidates int `json:"totalCandidates"`
				SkippedTooLarge int `json:"skippedTooLarge"`
				Bounded         int `json:"bounded"`
			} `json:"stats"`
		} `json:"cases"`
	}
	loadJSON(t, "goldens/walk.json", &golden)

	want := make(map[string]int, len(golden.Cases))
	for i, g := range golden.Cases {
		want[g.Name] = i
	}
	if len(cases.Cases) != len(golden.Cases) {
		t.Fatalf("walk cases = %d, goldens = %d", len(cases.Cases), len(golden.Cases))
	}
	for _, c := range cases.Cases {
		t.Run(c.Name, func(t *testing.T) {
			idx, ok := want[c.Name]
			if !ok {
				t.Fatalf("no golden for walk case %s", c.Name)
			}
			g := golden.Cases[idx]
			root := t.TempDir()
			materialize(t, root, c)

			res, err := clonetree.New().Walk(t.Context(), root)
			if err != nil {
				t.Fatalf("Walk(%s) error = %v", c.Name, err)
			}
			if diff := cmp.Diff(g.Files, res.Files, cmpopts.EquateEmpty()); diff != "" {
				t.Errorf("Walk(%s) files mismatch (-node +go):\n%s", c.Name, diff)
			}
			wantStats := domain.WalkStats{TotalCandidates: g.Stats.TotalCandidates, SkippedTooLarge: g.Stats.SkippedTooLarge, Bounded: g.Stats.Bounded}
			if diff := cmp.Diff(wantStats, res.Stats); diff != "" {
				t.Errorf("Walk(%s) stats mismatch (-node +go):\n%s", c.Name, diff)
			}
		})
	}
}
